import{_ as n,o as t,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const r="/assets/einrichten.c2w8hXiC.png",b=JSON.parse('{"title":"Installation und Voraussetzungen","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/01.erste-schritte/01.installation.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/erste-schritte/installation.md","filePath":"de/adapter/sourceanalytix/erste-schritte/installation.md","lastUpdated":null}'),s={name:"de/adapter/sourceanalytix/erste-schritte/installation.md"};function o(l,e,d,u,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="installation-und-voraussetzungen" tabindex="-1">Installation und Voraussetzungen <a class="header-anchor" href="#installation-und-voraussetzungen" aria-label="Permalink to &quot;Installation und Voraussetzungen&quot;">​</a></h1><p><a id="requirements-sourceanalytix-have-node-js"></a></p><h2 id="welche-voraussetzungen-braucht-sourceanalytix-node-js-js-controller-admin" tabindex="-1">Welche Voraussetzungen braucht SourceAnalytix (Node.js, js-controller, Admin)? <a class="header-anchor" href="#welche-voraussetzungen-braucht-sourceanalytix-node-js-js-controller-admin" aria-label="Permalink to &quot;Welche Voraussetzungen braucht SourceAnalytix (Node.js, js-controller, Admin)?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 braucht SourceAnalytix Node.js 22, js-controller 6.0.11 und Admin 8.0.0 oder neuer. Admin 8 ist nötig, weil die Instanz-Einstellungsseite mit den Tabs „Übersicht&quot; und „Probleme&quot; aus Bausteinen von Admin 8 besteht.</p><table tabindex="0"><thead><tr><th></th><th>ab v0.7.0</th><th>v0.6.0 bis v0.6.x</th></tr></thead><tbody><tr><td>Node.js</td><td>22 oder neuer</td><td>22 oder neuer</td></tr><tr><td>js-controller</td><td>6.0.11 oder neuer</td><td>6.0.11 oder neuer</td></tr><tr><td>Admin</td><td>8.0.0 oder neuer</td><td>7.8.23 oder neuer</td></tr></tbody></table><p>Die Versionen prüfst du in der Konsole mit <code>iobroker -v</code> (js-controller) und <code>node -v</code> (Node.js). Erfüllt dein System eine Voraussetzung nicht, aktualisiere zuerst diese Komponente und danach SourceAnalytix. v0.6.0 bis v0.6.x laufen mit Admin 7.8 und mit Admin 8. Ältere Angaben aus dem Forum wie „läuft mit Admin 6&quot; gelten nicht mehr.</p><h3 id="wenn-sourceanalytix-nach-einem-update-von-node-js-nicht-startet" tabindex="-1">Wenn SourceAnalytix nach einem Update von Node.js nicht startet <a class="header-anchor" href="#wenn-sourceanalytix-nach-einem-update-von-node-js-nicht-startet" aria-label="Permalink to &quot;Wenn SourceAnalytix nach einem Update von Node.js nicht startet&quot;">​</a></h3><p>Steht im Log nach einem Update von Node.js <code>TypeError: Class extends value … is not a constructor or null</code>, ist meist der js-controller zu alt. Aktualisiere den js-controller, führe in der Konsole <code>iob fix</code> aus und starte die Instanz neu. Läuft ioBroker in Docker, aktualisierst du stattdessen das Container-Image und spielst bei Bedarf dein Backup zurück.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a> · <a href="./../fehlerbehebung/log-meldungen#installation-admin-display-problems">Probleme bei Installation und Admin-Anzeige</a></p><p><a id="install-sourceanalytix-create-instance"></a></p><h2 id="wie-installiere-ich-sourceanalytix-und-lege-eine-instanz-an" tabindex="-1">Wie installiere ich SourceAnalytix und lege eine Instanz an? <a class="header-anchor" href="#wie-installiere-ich-sourceanalytix-und-lege-eine-instanz-an" aria-label="Permalink to &quot;Wie installiere ich SourceAnalytix und lege eine Instanz an?&quot;">​</a></h2><p><strong>Kurz:</strong> Stelle in den ioBroker-Systemeinstellungen das Repository „latest&quot; (Beta) ein und installiere SourceAnalytix im Reiter „Adapter&quot;. Dabei legt Admin die Instanz <code>sourceanalytix.0</code> an. Danach öffnest du die Einstellungen der Instanz und richtest im Tab „Übersicht&quot; deine erste Quelle ein.</p><p>SourceAnalytix steht derzeit nur im Repository „latest&quot;, nicht in „stable&quot;. In „stable&quot; kommt es erst nach einer Testphase. Mit „stable&quot; findest du es deshalb in der Adapterliste nicht.</p><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Prüfe die <a href="#requirements-sourceanalytix-have-node-js">Voraussetzungen</a>, vor allem Admin 8.</li><li>Öffne in Admin die Systemeinstellungen und wähle unter „Repositories&quot; das Repository „latest&quot; (Beta) als aktives Repository.</li><li>Öffne den Reiter „Adapter&quot;, aktualisiere die Adapterliste und suche nach „SourceAnalytix&quot;.</li><li>Installiere den Adapter. Admin legt dabei die Instanz <code>sourceanalytix.0</code> an und startet sie.</li><li>Öffne im Reiter „Instanzen&quot; die Einstellungen von <code>sourceanalytix.0</code>. Im Tab „Übersicht&quot; steht die Karte „SourceAnalytix einrichten&quot; mit den Schritten „Preis anlegen&quot;, „Quelle hinzufügen&quot; und „Werte ansehen&quot;.</li><li>Lege im Tab „Preisdefinitionen&quot; mindestens eine Preisdefinition an, zum Beispiel für Strom in kWh, und speichere. Speichern startet den Adapter neu.</li><li>Klicke im Tab „Übersicht&quot; auf „Erste Quelle hinzufügen&quot;. Wie es weitergeht, steht unter <a href="./erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a>.</li></ol><p><img src="'+r+'" alt="Tab „Übersicht“ direkt nach der Installation mit der Karte „SourceAnalytix einrichten“"></p><p>Die Tabs „Übersicht&quot; und „Probleme&quot; brauchen eine laufende Instanz. Ist sie gestoppt, steht oben „Instanz läuft nicht&quot; mit dem Knopf „Starten&quot;. Alle Aktionen mit ⚡ sind dann gesperrt.</p><h3 id="es-gibt-keine-instanz" tabindex="-1">Es gibt keine Instanz <a class="header-anchor" href="#es-gibt-keine-instanz" aria-label="Permalink to &quot;Es gibt keine Instanz&quot;">​</a></h3><p>Hast du SourceAnalytix über die Konsole mit npm oder über eine GitHub-Adresse installiert, legt ioBroker keine Instanz an. Lege sie dann selbst mit dem Plus-Symbol an, das in Admin eine Instanz hinzufügt. Eine Instanz reicht für alle Quellen.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Eine Installation über die GitHub-Adresse ist nur zum Testen gedacht, wenn der Entwickler dazu aufruft. Admin zeigt für eine solche Installation keine Updates an. Wie du zurück zum Repository „latest&quot; kommst, steht unter <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a>.</p></div><p><strong>Bis v0.6.x:</strong> Die Instanz-Einstellungen enthalten nur „Haupteinstellungen&quot; und „Preisdefinitionen&quot;. Quellen aktivierst du dort am Datenpunkt im Reiter „Objekte&quot; über das Schraubenschlüssel-Symbol.</p><p><strong>Siehe auch:</strong> <a href="#need-several-instances-versions-side">Brauche ich mehrere Instanzen?</a> · <a href="./erster-zaehler#configure-sourceanalytix-datapoint">Mein erster Zähler</a></p><p><a id="need-several-instances-versions-side"></a></p><h2 id="brauche-ich-mehrere-instanzen-oder-versionen-nebeneinander" tabindex="-1">Brauche ich mehrere Instanzen oder Versionen nebeneinander? <a class="header-anchor" href="#brauche-ich-mehrere-instanzen-oder-versionen-nebeneinander" aria-label="Permalink to &quot;Brauche ich mehrere Instanzen oder Versionen nebeneinander?&quot;">​</a></h2><p><strong>Kurz:</strong> Nein. Eine Instanz verarbeitet beliebig viele Quellen, jede mit eigenen Einstellungen. Zwei Versionen von SourceAnalytix nebeneinander gibt es nicht, ioBroker installiert von jedem Adapter genau eine Version.</p><h3 id="eine-instanz-fur-alles" tabindex="-1">Eine Instanz für alles <a class="header-anchor" href="#eine-instanz-fur-alles" aria-label="Permalink to &quot;Eine Instanz für alles&quot;">​</a></h3><p>Die Einstellungen einer Quelle gelten je Instanz. Sie stehen am Datenpunkt unter <code>common.custom.sourceanalytix.&lt;Instanz&gt;</code>, und jede Instanz rechnet nur mit den Quellen, die für sie aktiviert sind. Auch die Tabs „Übersicht&quot; und „Probleme&quot; zeigen nur die Quellen dieser Instanz. Eine zweite Instanz bringt also nichts, außer du willst bewusst getrennte Ordner <code>sourceanalytix.0</code> und <code>sourceanalytix.1</code>.</p><p>Mehrere Instanzen laufen immer mit derselben installierten Version. Eine neue Version testest du deshalb nicht neben der alten, sondern nach einem Backup als Update. Wie du bei Problemen zurückgehst, steht unter <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Downgrade</a>.</p><h3 id="eine-uberzahlige-instanz-entfernen" tabindex="-1">Eine überzählige Instanz entfernen <a class="header-anchor" href="#eine-uberzahlige-instanz-entfernen" aria-label="Permalink to &quot;Eine überzählige Instanz entfernen&quot;">​</a></h3><p>Eine zweite Instanz entsteht oft unbemerkt, etwa wenn du nach einer GitHub-Installation SourceAnalytix noch einmal aus dem Repository installierst. So räumst du auf:</p><ol><li>Prüfe im Reiter „Objekte&quot;, unter welcher Instanz deine Werte liegen, also ob deine Ordner unter <code>sourceanalytix.0</code> oder unter <code>sourceanalytix.1</code> stehen.</li><li>Lösche im Reiter „Instanzen&quot; die überzählige Instanz mit dem Papierkorb-Symbol.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Beim Löschen einer Instanz verschwinden auch ihre Ordner mit allen Werten. Lösche nie die Instanz, unter der deine Daten liegen. Willst du nur eine einzelne Quelle stilllegen, nimm bei der Quelle die Aktion „Deaktivieren&quot;.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Datenpunkt deaktivieren oder Quelle entfernen</a></p>',33)])])}const p=n(s,[["render",o]]);export{b as __pageData,p as default};
